/**
 * VitePress's default theme in the Pixel design system, copied from pixelbar.nl/pixel
 * the way spacestate does it: `pixel.css` is generated by `just pixel-theme` and
 * `Mermaid.vue` draws diagrams in the Pixel colours. The accept API page loads
 * vitepress-openapi and `openapi.css` itself (`AcceptApi.vue`).
 */
import type { Theme } from "vitepress";
import DefaultTheme from "vitepress/theme-without-fonts";
import AcceptApi from "./AcceptApi.vue";
import Mermaid from "./Mermaid.vue";
// Fonts are self-hosted, as on /pixel: no request to Google from a visitor's browser.
import "@fontsource/ibm-plex-mono/400.css";
import "@fontsource/ibm-plex-mono/500.css";
import "@fontsource/ibm-plex-sans/400.css";
import "@fontsource/ibm-plex-sans/400-italic.css";
import "@fontsource/ibm-plex-sans/500.css";
import "@fontsource/ibm-plex-sans/600.css";
import "@fontsource/pixelify-sans/500.css";
import "@fontsource/pixelify-sans/600.css";
import "./pixel.css";

export default {
	extends: DefaultTheme,
	enhanceApp({ app }) {
		app.component("AcceptApi", AcceptApi);
		app.component("Mermaid", Mermaid);
	},
} satisfies Theme;
